import { fastFloor } from "utils";

export const getEdgePoints = (
  x: number,
  y: number,
  width: number,
  tileWidth: number,
  tileHeight: number,
) => {
  const leftTopX = fastFloor((x - width) / tileWidth);
  const leftTopY = fastFloor((y - width) / tileHeight);
  const rightBottomX = Math.ceil((x + width) / tileWidth);
  const rightBottomY = Math.ceil((y + width) / tileHeight);

  return {
    leftTopX,
    leftTopY,
    rightBottomX,
    rightBottomY,
  };
};
